function R() { let r=document.body.dataset.page||"", v=r==="home"? "":(V[r]? r:""); const params=new URLSearchParams(location.search); if (v==="detail"&&params.has("id")) { const id=Number(params.get("id")); if (Number.isInteger(id)&&P[id]) ST.cur=id } if (v==="admin"&&!ST.auth) { location.href="login.php"; return } if (v==="login"&&ST.auth) { location.href="admin.php"; return } $("#app").innerHTML=H(v)+(V[v]())+F; if (v==="po") pv(); saveState() }
