function send() { const g=i => $("#"+i).value.trim(); if (!g("nm")||!g("nim")||!g("wa")) { alert("Lengkapi nama, NIM, dan nomor WA dulu ya."); return } const l=ST.cart.filter(c => c.on), c=l[0]||{ id: ST.cur, s: ST.size, q: ST.qty }, n=190+ST.orders.length, o={ id: "PO-2026-TI125-0"+n, nama: g("nm"), nim: g("nim"), kelas: g("kl"), item: P[c.id].n, uk: c.s, q: c.q, total: total()||P[c.id].p*c.q, skema: ST.po.bayar? "Lunas":"DP", st: "Pesanan Baru", ambil: ST.po.ambil? "Kirim ke alamat rumah":"Gedung Sekretariat UKM USMA" }; ST.orders.unshift(o); ST.found=o; ST.cart=ST.cart.filter(c => !c.on); window.open("https://wa.me/6281200000000?text="+encodeURIComponent($("#pv").textContent.replace("PO-2026-TI125-0190", o.id))); location.href="lacak.php" }
function add(id, s, q, go) { const p=P[id]; if (!p) { alert("Produk tidak ditemukan"); return } const stock=(p.st||Object.fromEntries(p.sz.map(x => [x.u, x.s])))[s]||0; if (!stock) { alert("Stok ukuran "+s+" habis"); return } const e=ST.cart.find(c => c.id==id&&c.s==s); if (e) { e.q=Math.min(stock, e.q+q); e.on=true } else ST.cart.push({ id, s, q: Math.min(stock, q), on: true }); saveState(); ST.cur=id; location.href=go? "po.php":"keranjang.php"; return }
function sq() { ST.q=$("#q").value; ST.page=1; R() }
function cari() { const v=$("#lk").value.trim().toUpperCase(); ST.found=ST.orders.find(o => o.id==v)||null; if (!ST.found) alert("Nomor pesanan tidak ditemukan"); R() }
