function setSt(d) { const o=ST.orders[ST.sel], n=S3.indexOf(o.st)+d; if (n<0||n>2) return; const go=() => { o.st=S3[n]; R() }; d<0? ask("Kembalikan status "+o.id+" ke "+S3[n]+"?", go):go() }
function plist() { const q=(ST.pq||"").toLowerCase(), L=P.filter(p => p.n.toLowerCase().includes(q)); return L.length? L.map(p => `<div class="pr2 ${p.id==ST.ep? "on":""}">${productImage(P[p.id], 56)}<div style="flex:1;min-width:0"><b>${p.n}</b><br><small class="mut">${p.c} - ${rp(p.p)} - Stok ${Object.values(p.st).reduce((a, b) => a+b, 0)} pcs</small></div><button class="ch" style="color:#2b4a9e;border-color:#2b4a9e" onclick="ST.ep=${p.id};ST.ez=P[${p.id}].sz.map(x=>({...x}));R()">Edit</button><button class="ch" style="color:#c33;border-color:#c33" onclick="delP(${p.id})">Hapus</button></div>`).join(""):`<p class="mut">Produk tidak ditemukan.</p>` }
function PE() { const e=P[ST.ep], f=(l, i, v, t="text") => `<label style="font-size:11px">${l}</label><input class="f" id="${i}" type="${t}" value="${String(v).replace(/"/g, "&quot;")}">`; return `<div class="two" style="grid-template-columns:1.1fr 1fr;align-items:start"><div class="card"><b style="font-size:16px">Edit PO / Produk</b><p class="mut" style="font-size:11px;margin:4px 0 12px">Pilih produk untuk mengubah detail dan stok, atau hapus dari katalog (${P.length} produk)</p><input class="f" placeholder="Cari nama produk..." value="${ST.pq||""}" oninput="ST.pq=this.value;document.getElementById('pl').innerHTML=plist()" style="margin-bottom:12px"><div id="pl">${plist()}</div></div><div class="card" style="background:#fbfcff">${e? `<b style="font-size:16px">Edit Produk : ${e.n}</b>${f("Nama Produk", "ep_n", e.n)}<label style="font-size:11px">Kategori</label><select class="f" id="ep_c">${["Seragam", "Kemeja", "Jaket", "Topi", "Dasi", "Aksesoris"].map(c => `<option ${c==e.c? "selected":""}>${c}</option>`).join("")}</select>${f("Harga Jual Satuan (Rp)", "ep_p", e.p, "number")}<label style="font-size:11px">Ganti Foto Produk (opsional)</label><input class="f" id="ep_img" type="file" accept="image/*"><label style="font-size:11px">Tabel Ukuran & Stok (semua bisa diedit)</label>${szHTML("ez")}<label style="font-size:11px">Deskripsi Bahan & Spesifikasi</label><textarea class="f" id="ep_d" rows="4">${e.dc}</textarea><div style="text-align:right;margin-top:14px"><button class="btn" style="background:#fff;color:#888;border:1px solid #bbb;margin-right:8px" onclick="ST.ep=null;R()">Batal</button><button class="btn" onclick="saveP()">Simpan Perubahan</button></div>`:`<div style="text-align:center;padding:60px 10px;color:var(--g)"><div style="font-size:34px">✎</div><b>Belum ada produk dipilih</b><p class="mut">Klik tombol Edit pada salah satu produk untuk mengubah detailnya.</p></div>`}</div></div>` }
function saveP() { const e=P[ST.ep], g=i => document.getElementById(i).value; if (!g("ep_n").trim()) { alert("Nama produk tidak boleh kosong"); return } const rz=szRead(); if (!rz) return; const apply=img => { e.n=g("ep_n").trim(); e.c=g("ep_c"); e.p=Math.max(0, +g("ep_p")||0); e.sz=rz; e.dc=g("ep_d"); if (img) e.img=img; saveState(); alert("Perubahan PO/produk disimpan"); R() }; const file=document.getElementById("ep_img")?.files?.[0]; if (file) { const rd=new FileReader(); rd.onload=() => apply(String(rd.result)); rd.readAsDataURL(file) } else apply(null) }
function delP(i) { if (P.length<2) { alert("Minimal harus ada 1 produk di katalog"); return } ask('Hapus produk "'+P[i].n+'" dari katalog?', () => { P.splice(i, 1); P.forEach((p, j) => p.id=j); ST.cart=ST.cart.filter(c => c.id!=i).map(c => ({ ...c, id: c.id>i? c.id-1:c.id })); ST.cur=ST.cur==i? 0:ST.cur>i? ST.cur-1:ST.cur; ST.ep=ST.ep==i? null:ST.ep>i? ST.ep-1:ST.ep; R() }, "#d9434f") }
function mkP(o) { return Object.defineProperty(o, "st", { get() { return Object.fromEntries(this.sz.map(x => [x.u, x.s])) } }) }
const e_=s => String(s).replace(/"/g, "&quot;");
function szHTML(k) { return `<div id="szt"><table><thead><tr><th>Ukuran</th><th>Lingkar Dada (cm)</th><th>Panjang (cm)</th><th>Stok Kuota</th><th>Aksi</th></tr></thead><tbody>${ST[k].map((r, i) => `<tr><td><input class="zi" value="${e_(r.u)}" placeholder="M"></td><td><input class="zi" type="number" min="0" value="${r.d}"></td><td><input class="zi" type="number" min="0" value="${r.l}"></td><td><input class="zi" type="number" min="0" value="${r.s}"></td><td><button class="dl" onclick="szOp('${k}','del',${i})">Hapus</button></td></tr>`).join("")}</tbody></table><button class="ad" onclick="szOp('${k}','add')">+ Tambah Ukuran</button></div>` }
function szRows() { return Array.from(document.querySelectorAll("#szt tbody tr")).map(tr => { const v=tr.querySelectorAll("input"); return { u: v[0].value.trim(), d: +v[1].value||0, l: +v[2].value||0, s: Math.max(0, parseInt(v[3].value)||0) } }) }
function szOp(k, a, i) { const r=szRows(); if (a=="add") r.push({ u: "", d: 0, l: 0, s: 0 }); else r.splice(i, 1); ST[k]=r; document.getElementById("szt").outerHTML=szHTML(k) }
function szRead() { const r=szRows(); if (!r.length) { alert("Tambahkan minimal 1 ukuran"); return null } if (r.some(x => !x.u)) { alert("Nama ukuran tidak boleh kosong"); return null } if (new Set(r.map(x => x.u.toUpperCase())).size<r.length) { alert("Nama ukuran tidak boleh sama"); return null } return r }
function toast(m) { const d=document.createElement("div"); d.textContent=m; d.style.cssText="position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:#14284f;color:#fff;padding:12px 20px;border-radius:10px;font:italic 600 13px Poppins,sans-serif;z-index:99;box-shadow:0 6px 18px #0004;max-width:90vw;text-align:center"; document.body.appendChild(d); setTimeout(() => d.remove(), 2800) }
window.alert=toast;
function ask(m, cb, col) { const o=document.createElement("div"); o.style.cssText="position:fixed;inset:0;background:#0007;display:grid;place-items:center;z-index:99"; o.innerHTML='<div style="background:#fff;border-radius:14px;padding:22px;max-width:360px;width:88%;text-align:center"><p style="margin:0 0 16px;font-weight:600"></p><button class="btn" style="background:#fff;color:#888;border:1px solid #bbb;margin-right:8px" id="no">Batal</button><button class="btn" id="ya">Ya, lanjutkan</button></div>'; o.querySelector("p").textContent=m; o.querySelector("#ya").style.background=col||"#3d7a52"; document.body.appendChild(o); o.querySelector("#no").onclick=() => o.remove(); o.querySelector("#ya").onclick=() => { o.remove(); cb() } }
function addP() { const g=i => document.getElementById(i).value; if (!g("np").trim()) { alert("Isi nama produk"); return } const rz=szRead(); if (!rz) return; const make=img => { P.unshift(mkP({ id: 0, n: g("np").trim(), c: g("kp")||"Aksesoris", p: +g("hg")||0, sz: rz, dc: g("ds"), img: img||"" })); P.forEach((p, i) => p.id=i); ST.cart=ST.cart.map(c => ({ ...c, id: c.id+1 })); ST.cur++; if (ST.ep!=null) ST.ep++; ST.nz=[{ u: "S", d: 96, l: 64, s: 30 }]; saveState(); alert("Pre-Order dibuka, produk muncul di katalog"); location.href="katalog.php" }; const file=document.querySelector('input[type=file][accept="image/*"]')?.files?.[0]; if (file) { const rd=new FileReader(); rd.onload=() => make(String(rd.result)); rd.readAsDataURL(file) } else make("") }
function inn() { if ($("#em").value.trim().toLowerCase()=="admin@usma.polinema.ac.id"&&$("#pw").value=="admin123") { ST.auth=true; try { sessionStorage.setItem("adm", "1") } catch (e) { } ST.tab="rekap"; saveState(); location.href="admin.php" } else $("#er").textContent="Email atau kata sandi salah. Coba lagi." }
function out() { ST.auth=false; try { sessionStorage.removeItem("adm") } catch (e) { } saveState(); location.href="index.php" }
function sl(d) { ST.slide=(ST.slide+d+4)%4; R() }
let mo=0, mk=0, mp=0; (function f() { const t=document.getElementById("tr"); if (t) { const h=t.scrollWidth/3, sp=mp||matchMedia("(prefers-reduced-motion:reduce)").matches? 0:.7; mo=((mo+sp+mk)%h+h)%h; mk*=.92; t.style.transform=`translateX(${-mo}px)` } requestAnimationFrame(f) })();
setInterval(() => { if ((document.body.dataset.page||"")==="home") sl(1) }, 5000);
addEventListener("hashchange", () => { window.scrollTo(0, 0); R() }); R();
